<script lang="ts">
    import { gatherRecentGrades } from "./gatherRecentGrades"
    import { gatherNotifications } from "$components/notifications/notifications";
    import RecentsDisplay from "./RecentsCard.svelte";
    import type { RecentItem } from "./types";
    import { neoUniversisGet } from "$lib/dataService";

    export let maxCards = 6;

    const RECENT_ITEMS_CACHE_KEY = "recentItems";

    function cacheRecentItems(recentItems: RecentItem[]) {
        localStorage.setItem(RECENT_ITEMS_CACHE_KEY, JSON.stringify(recentItems));
    }

    function getCachedRecentItems(): RecentItem[] {
        const cachedItems = localStorage.getItem(RECENT_ITEMS_CACHE_KEY);
        // Never show a cached easter egg before checking this student's eligibility.
        return cachedItems ? (JSON.parse(cachedItems) as RecentItem[]).filter(item => !(item.id === 666)) : [];
    }

    async function gatherRecentItems(): Promise<RecentItem[]> {
        // Temporary ACM easter egg: CS undergraduates in years 1–2 only.
        const showACMNotification = neoUniversisGet(
            'Students/me?$expand=studyProgram($expand=studyLevel), department',
            { lifetime: 86000 }
        ).then(student => String(student?.department?.id) === "64"
            && student?.studyProgram?.studyLevel?.alternateName === "undergraduate"
            && [1, 2, 3, 4].includes(Number(student?.semester))
        ).catch(() => false);

        const notifications = await gatherNotifications({ days: 7 });
        const recentGrades = await gatherRecentGrades();

        const recentItems: RecentItem[] = [
            ...recentGrades.map((recentGrade: any): RecentItem => ({
                type: "recentGrade",
                content: recentGrade,
                id: recentGrade.courseExam.id
            })),
            ...notifications.map((notification: any): RecentItem => ({
                type: "notification",
                content: notification,
                id: notification.id
            }))
        ];

        cacheRecentItems(recentItems);
        if (await showACMNotification) recentItems.push({
                type: "notification",
                content: {
                    type: "aristomate",
                    subject: "Πληροφορική και εθελοντισμός: βρες την ομάδα σου στην ACM AUTh!",
                    body: `<div lang="el" style="line-height: 1.6; padding: 0 8px; overflow-wrap: anywhere;">
                    <img style="width: 60%;height: auto;margin: auto;" src="data:image/png;base64," alt="" width="512" height="640" />

                        <p>Έχετε ακούσει ποτέ για το <strong>ACM AUTh Student Chapter</strong>; Είναι η ομάδα που έφτιαξε αυτήν εδώ την εφαρμογή, το Aristomate! Αν θέλετε να μας γνωρίσετε καλύτερα, αυτή είναι η ευκαιρία σας! Η ετήσια recruitment εκδήλωσή μας είναι εδώ για να σας παρουσιάσει τις δράσεις, τα branches και το όραμά μας! 💙</p>
                        <p>Ελάτε να γνωρίσετε από κοντά το επίσημο φοιτητικό παράρτημα της ACM στο Αριστοτέλειο Πανεπιστήμιο Θεσσαλονίκης και να ανακαλύψετε όσα μπορούμε να δημιουργήσουμε μαζί! Από projects και workshops μέχρι διοργάνωση εκδηλώσεων, στην ACM μπορείς να συνδυάσεις την πληροφορική με τον εθελοντισμό, να αναπτύξεις τα soft skills σου και να αφήσεις το αποτύπωμά σου στην πανεπιστημιακή κοινότητα.</p>
                        <p>🗓 <strong>When:</strong> Δευτέρα 19 Οκτωβρίου, στις <strong>18:00</strong><br>
                        📍 <strong>Where:</strong> Αίθουσα Δ22, Σχολή Θετικών Επιστημών</p>
                        <p>Δήλωσε συμμετοχή στην φόρμα που βρίσκεται στο παρακάτω link:<br>
                        <a href="https://forms.gle/UmK6HNLTVEiHVTMx9" target="_blank" rel="noopener noreferrer" style="color: #3880ff;"><strong>https://forms.gle/UmK6HNLTVEiHVTMx9</strong></a></p>
                        <p>και σε περιμένουμε να γνωριστούμε. See you there! ✨</p>
                        </div>`,
                    url: "https://forms.gle/UmK6HNLTVEiHVTMx9",
                    sender: "Meet ACM AUTh | Recruitment",
                    dateReceived: new Date("2026-10-14T10:24:00"),
                    id: 666
                },
                id: 666,
        });
        return recentItems;
    }

    const recentItemsFromCache = getCachedRecentItems();
</script>

{#await gatherRecentItems()}
    <RecentsDisplay recentItems={recentItemsFromCache} {maxCards} />
{:then recentItemsList}
    <RecentsDisplay recentItems={recentItemsList} {maxCards} />
{/await}
